// The app's icons: Phosphor (D-046), Bold in the interface and Duotone on tool tiles. Glyphs come from glyphs.ts,
// generated by scripts/icons.ts with only the weights we use.
import { makeIcon, type IconProps } from "./glyph";
import { glyphs } from "./glyphs";

export type { IconProps };

const glyph = (name: string, weight?: string) => makeIcon(glyphs, name, weight);

// Interface
export const CloseIcon = glyph("x");
export const GripIcon = glyph("dots-six-vertical");
export const CaretUpIcon = glyph("caret-up");
export const CaretDownIcon = glyph("caret-down");
